import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { componentAttrs } from "../_utils/component.helper";

const CHEVRON_LEFT_SVG =
  '<svg viewBox="0 0 16 16" width="12" height="12" fill="none" aria-hidden="true" focusable="false"><path d="M10 4 6 8l4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';

/**
 * A Squiz Matrix Asset Listing, configured (in Matrix, not this codebase) as
 * a JSON feed with a Dynamic Parameter (Replacement Root Node) driven by the
 * `rootId` query param -- the same hardcoded feed already reused by
 * `image-gallery`/`card`/`document` this session. Not editor-configurable,
 * same convention established for all three.
 */
const ASSET_LISTING_BASE_URL = "https://nt.gov.au/web-design-system/listings/asset-children-json-feed";
const ROOT_ID_PARAM_NAME = "rootId";

export default {
  async main(input = {}, info = {}) {
    const { parentAsset = "" } = input;
    const attrs = componentAttrs("side-navigation", input);
    const currentAssetId = info?.ctx?.assetId;

    const [parent, siblings, currentPageChildren] = await Promise.all([
      resolveAsset(parentAsset, info?.fns),
      fetchChildren(parseAssetUriId(parentAsset)),
      fetchChildren(currentAssetId),
    ]);

    const items = siblings
      .map((child) => toNavItem(child, currentAssetId, currentPageChildren))
      .filter(Boolean);

    return renderSideNavigation(parent, items, attrs);
  },
};

/**
 * fns.resolveUri wraps its result in a { ok, data } envelope -- confirmed
 * against a live Squiz DXP backend (see card.spec.md assumption 4, the same
 * mechanism reused here). Checking for the `data` key's presence, not just
 * truthiness, avoids misreading a legitimate `{ data: null }` "not found"
 * envelope as the raw asset itself.
 */
async function resolveAsset(uri, fns) {
  if (!uri || typeof fns?.resolveUri !== "function") return null;
  try {
    const result = await fns.resolveUri(uri);
    return unwrapResolved(result);
  } catch {
    return null;
  }
}

function unwrapResolved(result) {
  if (!result || typeof result !== "object") return null;
  if ("data" in result) return result.data ?? null;
  return result;
}

/**
 * Fetches an asset's children (by raw ID, not a matrix-asset-uri) via a
 * plain unauthenticated fetch() against the Asset Listing JSON feed above --
 * not info.fns, which has no children-listing capability at all on this
 * tenant. Called twice from main(): once for `parentAsset` (-> the sibling
 * list) and once for `info.ctx.assetId` (-> the current page's own
 * sub-pages, nested under it -- see assumption 4). Each returned item's own
 * `id`/`name`/`url` is used directly (unlike `card`'s parentAsset feature,
 * this component doesn't need each child's metadata, only its label/link/
 * id, so no second fns.resolveUri() round-trip per child is needed here).
 * See side-navigation.spec.md assumption 1.
 */
async function fetchChildren(assetId) {
  if (!assetId) return [];

  const url = `${ASSET_LISTING_BASE_URL}?${ROOT_ID_PARAM_NAME}=${encodeURIComponent(assetId)}`;

  try {
    const res = await fetch(url);
    if (!res.ok) return [];
    const body = await res.json();
    return Array.isArray(body) ? body : [];
  } catch {
    return [];
  }
}

function parseAssetUriId(uri) {
  const match = /^matrix-asset:\/\/[a-zA-Z0-9.-]+\/(\d+)(?::.+)?$/.exec(String(uri ?? ""));
  return match ? match[1] : null;
}

/**
 * Maps one child from the Asset Listing feed onto a render-ready nav item.
 * `current` is a strict string-compared ID match against
 * `info.ctx.assetId` -- both are real Matrix asset IDs, so this is an exact
 * match, not a fuzzy URL/label comparison. See side-navigation.spec.md
 * assumption 2. When this item *is* the current page, its own children
 * (already fetched in main()) are attached and rendered nested beneath it --
 * see assumption 4. Non-current items never get nested children: only the
 * active page's own sub-pages are shown, not every sibling's.
 */
function toNavItem(child, currentAssetId, currentPageChildren) {
  if (!child || !child.url) return null;
  const current = currentAssetId != null && String(child.id) === String(currentAssetId);
  return {
    label: child.name || "",
    href: child.url,
    current,
    children: current ? currentPageChildren.map(toChildLink).filter(Boolean) : [],
  };
}

function toChildLink(child) {
  if (!child || !child.url) return null;
  return { label: child.name || "", href: child.url };
}

function renderSideNavigation(parent, items, attrs) {
  const backHtml = parent?.url
    ? /*html*/ `
    <a class="side-navigation__back" href="${escURL(parent.url)}">
      ${CHEVRON_LEFT_SVG}
      <span>${escHTML(parent.name || parent.short_name || "")}</span>
    </a>`
    : "";

  const itemsHtml = items
    .map((item) => {
      const contentHtml = item.current
        ? `<span class="side-navigation__link side-navigation__link--current" aria-current="page">${escHTML(item.label)}</span>`
        : `<a class="side-navigation__link" href="${escURL(item.href)}">${escHTML(item.label)}</a>`;

      const nestedHtml = item.children.length
        ? `<ol class="side-navigation__sublist">${item.children
            .map(
              (child) =>
                `<li class="side-navigation__subitem"><a class="side-navigation__link side-navigation__link--sub" href="${escURL(child.href)}">${escHTML(child.label)}</a></li>`,
            )
            .join("")}</ol>`
        : "";

      return `<li class="side-navigation__item${item.current ? " side-navigation__item--current" : ""}">${contentHtml}${nestedHtml}</li>`;
    })
    .join("");

  return /*html*/ `
<nav ${attrs} class="side-navigation" aria-label="Section navigation">
  ${backHtml}
  <ol class="side-navigation__list">
    ${itemsHtml}
  </ol>
</nav>
`;
}
