import squizStoryRenderer from "@ntgovernment/squiz-factory/plugins/squizStoryRenderer";
import squizInfoMock from "@ntgovernment/squiz-factory/plugins/squizInfo.mock";
import comp from "./main.js";

const squiz = squizStoryRenderer(comp.main);

export default {
  title: "dxp components/Side Navigation",
};

/**
 * `parentAsset` is resolved via info.fns.resolveUri (mocked below). Both the
 * sibling list and the current page's own nested children come from a plain
 * fetch() against the Asset Listing JSON feed, not info.fns -- squizInfoMock
 * only mocks info.fns, so this stubs the global fetch instead, conditional
 * on the URL so it doesn't interfere with anything else that might call
 * fetch(). The mock is `rootId`-aware, since main.js calls the same feed
 * twice with two different root IDs (the parent, for siblings; the current
 * page, for its own nested sub-pages) -- same pattern as image-gallery's own
 * Folder story, extended to distinguish which root is being asked for.
 */
const FAKE_PARENT_ASSET = {
  id: "5001",
  name: "Section page",
  url: "https://example.com/section-page",
};

const FAKE_SIBLINGS = [
  { id: "5002", name: "Sub-page one", url: "https://example.com/section-page/sub-page-one" },
  { id: "5003", name: "Sub-page two", url: "https://example.com/section-page/sub-page-two" },
  { id: "5004", name: "Sub-page three", url: "https://example.com/section-page/sub-page-three" },
  { id: "5005", name: "Sub-page four", url: "https://example.com/section-page/sub-page-four" },
];

const FAKE_NESTED_CHILDREN = [
  { id: "5006", name: "Nested page one", url: "https://example.com/section-page/sub-page-two/nested-page-one" },
  { id: "5007", name: "Nested page two", url: "https://example.com/section-page/sub-page-two/nested-page-two" },
];

const CHILDREN_BY_ROOT_ID = {
  5001: FAKE_SIBLINGS,
  5003: FAKE_NESTED_CHILDREN,
  // Used by the ParentUnresolvable story below -- a stand-in "section" id
  // whose own resolveUri() call is deliberately left unmocked (-> null), to
  // show the list still populates from the feed even when the back link
  // can't be resolved at all.
  9999: FAKE_SIBLINGS,
};

const realFetch = globalThis.fetch?.bind(globalThis);
globalThis.fetch = async (url, ...rest) => {
  if (typeof url === "string" && url.includes("asset-children-json-feed")) {
    const rootId = new URL(url).searchParams.get("rootId");
    return { ok: true, json: async () => CHILDREN_BY_ROOT_ID[rootId] ?? [] };
  }
  return realFetch(url, ...rest);
};

function mockInfoFor(currentAssetId) {
  return squizInfoMock({
    ctx: { assetId: currentAssetId },
    mock: {
      resolveUri: (uri) => (uri === "matrix-asset://ntg/5001" ? FAKE_PARENT_ASSET : null),
    },
  });
}

const defaultArgs = { parentAsset: "matrix-asset://ntg/5001" };
const defaultInfo = mockInfoFor("5002");
const defaultHtml = await squiz.markup(defaultArgs, defaultInfo);

export const Default = {
  render: () => squiz(defaultArgs, defaultInfo),
  parameters: {
    docs: {
      description: { story: "The current page (\"Sub-page one\") is highlighted -- bold, with a left border accent, rendered as non-interactive text rather than a link. It has no sub-pages of its own here, so nothing is nested beneath it." },
      source: { code: defaultHtml, language: "html", type: "code" },
    },
  },
};

const nestedInfo = mockInfoFor("5003");
const nestedHtml = await squiz.markup(defaultArgs, nestedInfo);

export const WithNestedSubPages = {
  render: () => squiz(defaultArgs, nestedInfo),
  parameters: {
    docs: {
      description: { story: "The current page (\"Sub-page two\") has its own sub-pages -- they render nested, indented, directly beneath it in the list." },
      source: { code: nestedHtml, language: "html", type: "code" },
    },
  },
};

const noCurrentInfo = mockInfoFor("9999");
const noCurrentHtml = await squiz.markup(defaultArgs, noCurrentInfo);

export const NoCurrentPageMatch = {
  render: () => squiz(defaultArgs, noCurrentInfo),
  parameters: {
    docs: {
      description: { story: "info.ctx.assetId doesn't match any child's id (e.g. this component placed on a page outside the section) -- the full list still renders, just with nothing highlighted." },
      source: { code: noCurrentHtml, language: "html", type: "code" },
    },
  },
};

const unresolvableArgs = { parentAsset: "matrix-asset://ntg/9999" };
const unresolvableInfo = mockInfoFor("5002");
const unresolvableHtml = await squiz.markup(unresolvableArgs, unresolvableInfo);

export const ParentUnresolvable = {
  render: () => squiz(unresolvableArgs, unresolvableInfo),
  parameters: {
    docs: {
      description: { story: "parentAsset fails to resolve via fns.resolveUri -- the back link is omitted entirely; the list (still fed by the mocked fetch()) renders independently." },
      source: { code: unresolvableHtml, language: "html", type: "code" },
    },
  },
};
